def _drain_output(self, timeout: float = 0.0) -> None:
    if self._closed:
        return

    # A continuously-writing interactive program must not prevent the
    # caller from regaining control when wait_sec is zero.
    for _ in range(64):
        try:
            chunk = self._child.read_nonblocking(size=4096, timeout=timeout)
